/* Design-only UI. All records are fixtures. No fetch, authentication, payments or API mutations. */
const model=window.EASYGAS_DESIGN;
const $=id=>document.getElementById(id);
const state={persona:'customer',screen:'c-home',theme:'light',view:'ready',role:'owner',quantity:2.5,capacity:12.5,category:'All',cart:1,location:'Lekki, Lagos',context:'products',history:[],completed:false,consent:false,noticeRead:false,formValues:{}};
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',bag:'M5 7h14l1 14H4L5 7Zm4 0V5a3 3 0 0 1 6 0v2',truck:'M2 5h12v12H2zM14 9h4l4 5v3h-8M7 17a2 2 0 1 0 0 .1M18 17a2 2 0 1 0 0 .1',wallet:'M20 7V4H4a2 2 0 0 0 0 4h17v12H4a2 2 0 0 1-2-2V6M21 12h-6v4h6',gift:'M3 8h18v4H3zM5 12v9h14v-9M12 8v13M12 8H8a3 3 0 1 1 3-3l1 3Zm0 0h4a3 3 0 1 0-3-3l-1 3Z',wrench:'M14 5a5 5 0 0 0-6 6L2 17a3 3 0 0 0 4 4l7-7a5 5 0 0 0 6-6l-4 3-3-3 3-4Z',bell:'M6 9a6 6 0 0 1 12 0v6l2 3H4l2-3V9m4 12h4',user:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM4 21v-2a8 8 0 0 1 16 0v2',users:'M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM3 21v-2a7 7 0 0 1 14 0v2M18 5a4 4 0 0 1 0 8m1 2a6 6 0 0 1 3 6',pin:'M20 9c0 6-8 13-8 13S4 15 4 9a8 8 0 1 1 16 0ZM15 9a3 3 0 1 1-6 0 3 3 0 0 1 6 0',chevron:'m9 5 7 7-7 7',arrow:'M4 12h16m-6-6 6 6-6 6',back:'M20 12H4m6-6-6 6 6 6',plus:'M12 5v14M5 12h14',search:'M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0m-2 6 6 6',shield:'M12 2 3 6v6c0 6 9 10 9 10s9-4 9-10V6l-9-4Zm-4 9 3 3 5-5',card:'M2 5h20v14H2zM2 9h20M6 15h3',clock:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0ZM12 6v6l4 2',check:'m5 12 4 4L19 6',calendar:'M4 5h16v17H4zM8 2v6m8-6v6M4 10h16m-12 4h1m3 0h1m3 0h1m-9 4h1m3 0h1',chart:'M4 21V12h3v9m3 0V6h3v15m3 0V2h3v19',box:'m3 7 9-5 9 5v10l-9 5-9-5V7Zm0 0 9 5 9-5M12 12v10M7 4l10 6',settings:'M9 2h6l1 4 4 1 2 5-3 3v5l-5 2-4-3-4 1-4-5 2-4-1-4 5-3 1-2Zm7 10a4 4 0 1 1-8 0 4 4 0 0 1 8 0',refresh:'M20 7A9 9 0 0 0 4 5L1 8m0-6v6h6m-3 9a9 9 0 0 0 16 2l3-3m0 6v-6h-6',logout:'M9 3H3v18h6m5-14 5 5-5 5m-7-5h12',download:'M12 2v13m-5-5 5 5 5-5M3 17v5h18v-5',upload:'M12 16V3m-5 5 5-5 5 5M3 17v5h18v-5',warning:'m12 2 11 20H1L12 2Zm0 6v6m0 3v1',headset:'M3 14v-3a9 9 0 0 1 18 0v3M3 12h4v7H3zm14 0h4v7h-4m4 0v3h-7',file:'M5 2h10l5 5v15H5V2Zm10 0v6h5M9 12h7m-7 4h7',flame:'M12 2c1 6 7 7 7 13a7 7 0 1 1-14 0c0-4 3-6 4-9 0 4 2 5 2 5s3-4 1-9Z',cylinder:'M8 2h8v5H8zM7 7h10l2 3v11H5V10l2-3Zm-2 8h14m-9-13v5m4-5v5',more:'M4 12h.1m7.9 0h.1m7.9 0h.1'};
const aliases={House:'home',ShoppingCart:'bag',Monitor:'card',UsersRound:'users',Headset:'headset',Package:'box',Warehouse:'box',Cylinder:'cylinder',Layers:'box',Truck:'truck',CalendarDays:'calendar',Wrench:'wrench',HardHat:'shield',FileText:'file',Wallet:'wallet',RefreshCw:'refresh',CreditCard:'card',ChartNoAxesCombined:'chart',ChartColumn:'chart',Megaphone:'bell',Lightbulb:'flame',Star:'gift',ShieldCheck:'shield',Settings:'settings',ClipboardList:'file',TriangleAlert:'warning',History:'clock',Rocket:'arrow',MessageSquareQuote:'file'};
function icon(name){name=aliases[name]||name;return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.box}"/></svg>`}
const money=n=>'₦'+Number(n).toLocaleString('en-NG');
const button=(text,go,kind='primary',attrs='')=>`<button class="${kind}" ${go?'data-go="'+go+'"':''} ${attrs}>${text}</button>`;
const action=(text,name,kind='primary',attrs='')=>button(text,null,kind,`data-action="${name}" ${attrs}`);
const pill=(text,tone='')=>`<span class="pill ${tone}"><span class="dot"></span>${text}</span>`;
const heading=(title,dest,label='See all')=>`<div class="section-heading"><h2>${title}</h2>${dest?button(label+' '+icon('arrow'),dest,'text-button'):''}</div>`;
const tile=(name,tone='')=>`<span class="icon-tile ${tone}">${icon(name)}</span>`;
const row=(title,sub,ico,go,extra='')=>`<${go?"button":"div"} class="list-row" ${go?'data-go="'+go+'"':''}>${tile(ico)}<span class="grow"><strong>${title}</strong>${sub?'<span>'+sub+'</span>':''}</span>${extra||icon('chevron')}</${go?"button":"div"}>`;
const note=text=>`<div class="notice">${icon('shield')}<p>${text}</p></div>`;
const card=html=>`<section class="card">${html}</section>`;
const field=(name,label,value='',type='text',more='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${more}></label>`;
const select=(name,label,options)=>`<label class="field">${label}<select name="${name}">${options.map(x=>`<option>${x}</option>`).join('')}</select></label>`;
const textarea=(name,label,value='')=>`<label class="field">${label}<textarea name="${name}" placeholder="${esc(value)}"></textarea></label>`;
const check=(text,name='confirm')=>`<label class="checkbox-row"><input type="checkbox" name="${name}" required><span>${text}</span></label>`;
const info=(ico,title,sub)=>`<div class="label-value">${icon(ico)}<div><strong>${title}</strong><span>${sub}</span></div></div>`;
const summary=()=>`<div class="summary-row"><span>Cooking gas · ${state.quantity} kg</span><strong>${money(state.quantity*1800)}</strong></div><div class="summary-row"><span>Delivery</span><strong>${money(5000)}</strong></div><div class="divider"></div><div class="summary-row total"><span>Total</span><strong>${money(state.quantity*1800+5000)}</strong></div>`;
const products=[{name:'6 kg empty cylinder',price:26000,kind:'Cylinders'},{name:'12.5 kg empty cylinder',price:42000,kind:'Cylinders'},{name:'Gas hose · 2 metres',price:3500,kind:'Accessories'},{name:'Gas regulator',price:4500,kind:'Accessories'},{name:'Double-burner cooker',price:18000,kind:'Cookers'},{name:'25 kg empty cylinder',price:60000,kind:'Cylinders'}];
function productCards(list=products.slice(0,2)){return `<div class="products">${list.map(p=>`<div class="product"><button class="product-art" data-go="c-product" aria-label="View ${p.name}" style="width:100%;border:0">${p.kind==='Cylinders'?'<img src="assets/cylinder.png" alt="Green EasyGas cylinder">':icon(p.kind==='Accessories'?'settings':'flame')}</button><h3>${p.name}</h3><div class="small-note">${p.kind==='Cylinders'?'Gas sold separately':p.kind}</div><div class="tiny-row"><span class="product-price">${money(p.price)}</span><button class="add-small" data-action="add" aria-label="Add ${p.name}">${icon('plus')}</button></div></div>`).join('')}</div>`}
function tabs(){const p=state.persona;let links=p==='customer'?[['home','Home','c-home'],['bag','Shop','c-shop'],['box','Activity','c-orders'],['wrench','Services','c-services'],['user','Account','c-account']]:p==='driver'?[['home','Today','d-home'],['truck','Deliveries','d-tasks'],['refresh','Sync','d-offline'],['user','Account','d-account']]:p==='technician'?[['home','Today','t-home'],['calendar','Agenda','t-agenda'],['file','Reports','t-history'],['user','Account','t-account']]:[['home',allowed('b-dashboard')?'Home':'Workspace',allowed('b-dashboard')?'b-dashboard':'b-workspace'],['box','Work',['b-orders','b-bookings','b-inventory','b-finance','b-products'].find(x=>allowed(x))||'b-workspace'],['shield','Approvals','b-approvals'],['chart','Insights','b-reports'],['more','More','b-workspace']].filter(x=>allowed(x[2]));return links.map(([i,l,g])=>`<button class="tab ${activeTab(g)?'active':''}" data-go="${g}" ${activeTab(g)?'aria-current="page"':''}>${icon(i)}<span>${l}</span></button>`).join('')}
function activeTab(g){if(state.screen===g)return true;if(state.persona!=='customer'&&(g.endsWith('-account')||g==='b-workspace')&&state.screen.startsWith('c-'))return true;if(state.persona==='customer'){if(g==='c-shop')return ['c-product','c-gas','c-cart','c-checkout','c-confirmation'].includes(state.screen);if(g==='c-orders')return ['c-order','c-track','c-refund'].includes(state.screen);if(g==='c-services')return ['c-service','c-book','c-bookings','c-booking','c-quote','c-report'].includes(state.screen);if(g==='c-account')return !['c-home','c-shop','c-product','c-gas','c-cart','c-checkout','c-confirmation','c-orders','c-order','c-track','c-refund','c-services','c-service','c-book','c-bookings','c-booking','c-quote','c-report'].includes(state.screen)}return false}
function screenMeta(){return model.screens.find(x=>x.id===state.screen)}
function appHeader(){const meta=screenMeta();const home=state.screen.endsWith('-home')||state.screen==='b-dashboard';if(state.screen==='a-welcome')return `<div class="head-row"><span class="head-title">Welcome to EasyGas</span>${button('Skip','c-home','text-button')}</div>`;if(home)return `<div class="head-row"><button class="text-button" style="color:var(--ink);display:block;text-align:left" data-action="location"><div class="head-small">${state.persona==='customer'?'Deliver to':state.persona==='business'?'Your workspace':'Assigned branch'}</div><div class="head-address">${icon('pin')}${state.persona==='customer'?state.location:'Lagos branch'}${icon('chevron')}</div></button><button class="circle-button" data-go="c-notices" aria-label="Notifications">${icon('bell')}<span class="counter-dot"></span></button></div>`;return `<div class="head-row"><button class="back-button" data-action="back" aria-label="Go back">${icon('back')}</button><span class="head-title">${meta?.title||'EasyGas'}</span><button class="circle-button quiet" data-go="${state.persona==='customer'?'c-cart':state.persona==='driver'?'d-support':state.persona==='technician'?'t-safety':'b-detail'}" aria-label="${state.persona==='customer'?'Open basket':'Get help'}">${icon(state.persona==='customer'?'bag':'more')}</button></div>`}
function orderCard(){return card(`<div class="row spread"><strong>EG-2048</strong>${pill(state.completed?'Delivered':'On the way')}</div><div class="divider"></div><div class="row"><img src="assets/cylinder.png" alt="Gas refill" style="width:48px;height:64px;object-fit:contain"><div class="grow"><h3>Cooking gas refill</h3><div class="small-note">${state.quantity} kg · Home delivery</div><strong>${money(state.quantity*1800+5000)}</strong></div></div><div class="btn-row">${button('View order','c-order','secondary')}${button('Track delivery','c-track')}</div>`)}
function timeline(){return `<div class="timeline">${[['Order confirmed','Today, 10:15 AM','check'],['Preparing your order','Today, 10:45 AM','box'],['Out for delivery','Today, 11:20 AM','truck'],['Delivered','Share your code after receiving all items','home']].map(([t,s,i],n)=>`<div class="time-step ${n<3?'done':''}"><span class="step-dot">${icon(i)}</span><div><strong>${t}</strong><p>${s}</p></div></div>`).join('')}</div>`}
function customerScreen(id){switch(id){
case 'c-home':return `<div class="eyebrow">YOUR EASYGAS</div><h1>Good morning,<br>Aisha.</h1><p>Good energy for everything you’re cooking.</p><div class="hero"><div class="eyebrow">MORE COOKING. LESS WORRY.</div><h2>A full kitchen.<br>A little less<br>to think about.</h2><p>Order just the gas you need.</p>${button('Order gas '+icon('arrow'),'c-gas')}<img class="hero-art" src="assets/cylinder.png" alt="EasyGas cylinder"></div><div class="quick-grid">${[['box','Orders','c-orders'],['wallet','Wallet','c-wallet'],['gift','Rewards','c-rewards'],['headset','Support','c-support']].map(([i,t,g])=>`<button class="quick" data-go="${g}">${tile(i,t==='Rewards'?'orange':'')}<span>${t}</span></button>`).join('')}</div>${heading('Your next refill','c-profile','View profile')}<div class="card green"><div class="row">${tile('calendar')}<div class="grow"><h3>Stay one step ahead.</h3><div class="small-note">Estimated in about 6 days</div></div></div><div class="progress"><span style="width:68%"></span></div><div class="small-note">Based on verified purchase history.</div><div class="btn-row">${button('Plan a refill','c-plans','secondary')}</div></div>${heading('Your delivery','c-orders')}${orderCard()}${heading('Kitchen essentials','c-shop')}${productCards()}${heading('A safer kitchen','c-services')}${card(`<div class="row">${tile('wrench','blue')}<div class="grow"><h3>Care for your equipment</h3><p style="margin:0">Servicing, installations & safety checks.</p></div></div>${button('Explore services '+icon('arrow'),'c-services','text-button')}`)}`;
case 'c-shop':return `<h1>For your kitchen.</h1><p>Everyday essentials. Dependable energy.</p><label class="search-input">${icon('search')}<input id="productSearch" placeholder="Search products…" aria-label="Search products"></label><div class="chips">${['All','Cylinders','Accessories','Cookers'].map(c=>`<button class="chip ${state.category===c?'active':''}" data-category="${c}">${c}</button>`).join('')}</div><div id="productResults">${productCards(products.filter(p=>state.category==='All'||p.kind===state.category))}</div><div class="fixed-cta">${button('Order a gas refill '+icon('flame'),'c-gas','secondary')}</div>`;
case 'c-product':return `<div class="product-art" style="height:240px"><img src="assets/cylinder.png" alt="Green EasyGas cylinder" style="height:220px;width:220px"></div><div class="section-gap">${pill('Gas cylinders')}<h1 style="margin-top:13px">12.5 kg empty cylinder</h1><p>Made for the meals and moments that matter.</p><h2 style="font-size:28px">₦42,000</h2></div><div class="row" style="margin:18px 0">${tile('shield')}<span class="small-note">Gas is sold separately. Eligible cylinders are checked before fulfilment.</span></div><div class="divider"></div><h3>About this product</h3><p>Empty LPG cylinder. Choose the right capacity for your kitchen, and add a gas refill separately.</p>${info('truck','Delivery to '+state.location,'Availability and delivery confirmed at checkout.')}<div class="btn-row">${action('Add to basket','add')}${button('Order gas','c-gas','secondary')}</div>`;
case 'c-gas':return `<div class="eyebrow">GAS, YOUR WAY</div><h1>How much do<br>you need?</h1><p>₦1,800/kg · One delivery fee of ₦5,000</p><div class="row" style="justify-content:center"><img src="assets/cylinder.png" alt="Gas cylinder" style="height:155px;object-fit:contain"></div><label class="field">Your cylinder capacity<select id="capacity">${[3,6,12.5,25,50].map(n=>`<option ${n===state.capacity?'selected':''} value="${n}">${n} kg cylinder</option>`).join('')}</select></label><label class="field">Gas quantity (kg)</label><div class="stepper"><button data-action="minus" aria-label="Reduce gas quantity">−</button><input id="gasQuantity" type="number" min="0.5" max="${state.capacity}" step="0.5" value="${state.quantity}" aria-label="Gas quantity in kilograms"><button data-action="plus" aria-label="Increase gas quantity">+</button></div><p style="margin-top:8px">Order an amount that fits your cylinder.</p>${row('Deliver to',state.location,'pin','c-addresses')}${card(summary())}${button('Continue '+icon('arrow'),'c-checkout')}`;
case 'c-cart':return `<h1>Your basket</h1><p>Good things for your kitchen.</p>${state.cart?card(`<div class="row">${tile('settings')}<div class="grow"><h3>Gas hose · 2 metres</h3><span class="small-note">${state.cart} item${state.cart>1?'s':''} · ${money(3500*state.cart)}</span></div>${action('Remove','remove','text-button')}</div>`):empty('bag','Your basket is empty','Find the right essentials for your kitchen.','c-shop','Explore products')}${card(`<h3>Need a refill too?</h3><p>Choose your gas quantity before checking out.</p>${button('Add cooking gas','c-gas','secondary')}`)}${state.cart?button('Continue to checkout','c-checkout'):''}`;
case 'c-checkout':return `<div class="segmented"><button class="active">1 · Address</button><button class="active">2 · Delivery</button><button class="active">3 · Review</button></div><h2>Let’s get it to you.</h2>${card(`<div class="row spread"><h3>Home</h3>${button('Change','c-addresses','text-button')}</div><p style="margin:7px 0 0">12 Adeola Street, Lekki Phase 1,<br>Lagos, Nigeria</p>`)}<form data-submit="checkout">${select('date','Delivery date',['Today · 29 Oct','Tomorrow · 30 Oct'])}${select('slot','Delivery window',['2 PM – 6 PM','8 AM – 12 PM','6 PM – 9 PM'])}<h3>How would you like to pay?</h3><label class="option"><input type="radio" name="payment" value="cod" checked>${tile('wallet')}<span class="grow"><strong>Cash on delivery</strong><span>Pay the exact amount at handover.</span></span></label><label class="option"><input type="radio" name="payment" value="credit">${tile('card')}<span class="grow"><strong>Purchase credit</strong><span>Available balance · ₦12,500</span></span></label>${note('Online card payments are currently unavailable.')}${card(`<h3>Order summary</h3><div class="divider"></div>${summary()}`)}${check('I confirm my address and delivery details.')}<button class="primary" type="submit">Confirm order · ${money(state.quantity*1800+5000)}</button></form><p class="center" style="margin-top:13px">Your total is confirmed before placing your order.</p>`;
case 'c-addresses':return `<h1>Where to?</h1><p>Choose the address for this delivery.</p>${['Home','Office'].map((x,i)=>`<label class="option"><input type="radio" name="address" ${!i?'checked':''}><span class="grow"><strong>${x}${!i?' · Default':''}</strong><span>${i?'25 Marina Road, Lagos Island':'12 Adeola Street, Lekki Phase 1'}, Lagos</span></span></label>`).join('')}${button(icon('plus')+' Add an address','c-addressform','secondary')}<div class="fixed-cta">${action('Use this address','select-address')}</div>`;
case 'c-addressform':return `<h1>Make yourself<br>easy to find.</h1><form data-submit="address">${field('label','Address label','Home','text','required')}${field('name','Recipient name','Aisha Bello','text','required autocomplete="name"')}${field('phone','Phone number','','tel','required placeholder="080…" autocomplete="tel"')}${textarea('address','Complete house address','House number, street, area, city and state')}${note('We’ll suggest a delivery location from your full address. You can review and change it.')}${select('area','Confirm delivery area',['Lekki','Victoria Island','Lagos Island','Ajah'])}${field('directions','Landmark or directions (optional)','','text','placeholder="Opposite the pharmacy"')}${check('Save as my default address.','default')}<button class="primary">Save address</button></form>`;
case 'c-confirmation':return `<div class="big-check">${icon('check')}</div><div class="center"><div class="eyebrow">ORDER EG-2048</div><h1>You’re all set.</h1><p>We’ll keep you updated as your order makes its way to you.</p></div>${card(`${info('calendar','Today · 2 PM – 6 PM','Your selected delivery window')}${info('pin','Home · '+state.location,'12 Adeola Street, Lekki Phase 1')}${info('wallet','Cash on delivery',money(state.quantity*1800+5000))}`)}${button('Track your order '+icon('arrow'),'c-track')}<div class="fixed-cta">${button('Back to home','c-home','secondary')}</div>`;
case 'c-orders':return `<h1>Your orders</h1><p>Every order. Every update. In one place.</p><div class="segmented"><button class="active" data-action="activeorders">Active</button><button data-action="pastorders">Past orders</button></div>${orderCard()}${card(row('EG-1986 · Delivered','12.5 kg gas refill · 12 Oct','check','c-order'))}`;
case 'c-order':return `<div class="row spread"><h1>EG-2048</h1>${pill(state.completed?'Delivered':'On the way')}</div><p>Placed today at 10:15 AM</p>${card(`<div class="row"><img src="assets/cylinder.png" alt="Cylinder" style="width:60px;height:85px;object-fit:contain"><div><h3>Cooking gas refill</h3><p style="margin:0">${state.quantity} kg · 12.5 kg cylinder</p></div></div><div class="divider"></div>${summary()}`)}${info('pin','Delivering to home','12 Adeola Street, Lekki Phase 1, Lagos')}${info('card','Cash on delivery','Payment confirmation appears after verification.')}${button('Track delivery','c-track')}<div class="fixed-cta">${button('Get help with this order','c-thread','secondary')}</div>${heading('After delivery')}<p>Refunds are reviewed after delivery and payment verification.</p>${button('View refund options','c-refund','secondary')}`;
case 'c-track':return `<div class="row spread"><div class="eyebrow">ORDER EG-2048</div>${pill('On the way')}</div><h1>Good energy<br>is on its way.</h1><p>Follow confirmed delivery updates below.</p>${timeline()}${card(`<div class="row"><div class="avatar">JE</div><div class="grow"><h3>James E.</h3><span class="small-note">Your assigned delivery partner</span></div>${icon('truck')}</div>`)}${card(`<h3>Your handover code</h3><div style="font-size:29px;letter-spacing:6px;font-weight:750;margin:12px 0">482 719</div><p style="margin:0">Share only after you receive <strong>all</strong> your items.</p>`)}<p>Live location and arrival estimates are unavailable. This timeline shows confirmed order events.</p>${button('Need help?','c-thread','secondary')}`;
case 'c-refund':return `<h1>Let’s put it right.</h1><p>Tell us which items need a refund. Your original order records stay unchanged.</p><form data-submit="refund">${card(`<h3>Order EG-1986</h3>${check('12.5 kg cooking gas refill','gas')}<label class="field">Returned gas quantity (kg)<input type="number" step="0.5" min="0.5" max="12.5" value="2.5"></label>`)}${select('reason','What happened?',['Choose a reason','Product issue','Incorrect quantity','Other'])}${textarea('details','A little more detail','Describe the issue…')}${note('Refunds require independent review. Approved amounts are credited according to the refund policy; this does not record a physical cylinder return.')}${check('I agree to receive an approved refund as EasyGas purchase credit.')}<button class="primary">Submit refund request</button></form>`;
case 'c-services':return `<div class="eyebrow">CARE FOR YOUR KITCHEN</div><h1>In good hands.</h1><p>Professional services for a safer home.</p><img class="auth-hero" src="assets/cooking.webp" alt="A home kitchen" style="height:155px;margin-bottom:14px">${[['Cooker servicing','Keep your cooker working well.','wrench'],['Cooker installation','A careful start for your kitchen.','flame'],['Gas safety check','Expert checks, peace of mind.','shield'],['Hose & regulator replacement','Genuine parts, expert fitting.','settings']].map(([t,s,i])=>card(row(t,s,i,'c-service'))).join('')}${button('View my appointments','c-bookings','secondary')}`;
case 'c-service':return `<div class="icon-tile blue" style="width:72px;height:72px;border-radius:21px;margin-bottom:20px">${icon('wrench')}</div><h1>Cooker servicing</h1><p>A little care goes a long way. Have your cooker assessed and serviced by eligible personnel.</p>${card(`<h3>What to expect</h3>${info('check','Equipment assessment','Tell us the make and the issue before your visit.')}${info('check','Clear quotation','Any additional work requires your approval.')}${info('check','Service report','Review the work and keep your report.')}`)}${note('Price, coverage and appointments depend on current service configuration. Extra materials are quoted separately.')}${button('Check availability','c-book')}`;
case 'c-book':return `<h1>A time that<br>works for you.</h1><form data-submit="booking">${select('service','Service',['Cooker servicing','Cooker installation','Gas safety check'])}${select('address','Visit address',['Home · Lekki, Lagos','Office · Lagos Island'])}${field('equipment','Equipment make / model','','text','required placeholder="e.g. 4-burner gas cooker"')}${textarea('issue','What should we know?','Tell us what needs attention.')}${select('date','Available date',['Tuesday, 3 November','Wednesday, 4 November'])}${select('slot','Available appointment',['10 AM – 12 PM','2 PM – 4 PM'])}${note('You’ll review the callout charge and terms before confirming. Additional work is quoted for your approval.')}${check('I have reviewed the service scope and booking terms.')}<button class="primary">Request appointment</button></form>`;
case 'c-bookings':return `<h1>Your appointments</h1><p>Care for your kitchen, all in one place.</p><div class="segmented"><button class="active">Upcoming</button><button data-go="c-report">History</button></div>${card(`<div class="row spread">${tile('wrench','blue')}${pill('Scheduled')}</div><h2 style="margin-top:17px">Cooker servicing</h2><p>Tuesday, 3 Nov · 10 AM – 12 PM<br>Home · Lekki, Lagos</p>${button('View appointment','c-booking','secondary')}`)}${button(icon('plus')+' Book a service','c-services')}`;
case 'c-booking':return `<div class="eyebrow">APPOINTMENT SV-1042</div><h1>Cooker servicing</h1>${pill('Scheduled')}${info('calendar','Tuesday, 3 November','10 AM – 12 PM')}${info('pin','Home · Lekki, Lagos','12 Adeola Street, Lekki Phase 1')}${info('user','Technician assignment','We’ll show your assigned technician here.')}${card(`<h3>Your equipment</h3><p>4-burner cooker · Uneven flame</p>${button('View quotation','c-quote','text-button')}`)}${button('Reschedule appointment','c-book','secondary')}<div class="btn-row">${action('Request cancellation','cancel-booking','secondary')}${button('Get help','c-thread','secondary')}</div>`;
case 'c-quote':return `<div class="eyebrow">QUOTATION / SV-1042</div><h1>Clear work.<br>Clear costs.</h1>${card(`<h3>Cooker servicing & hose replacement</h3><p>Quotation version 2 · Expires in 48 hours</p><div class="summary-row"><span>Labour</span><strong>₦8,000</strong></div><div class="summary-row"><span>Gas hose</span><strong>₦3,500</strong></div><div class="divider"></div><div class="summary-row total"><span>Total</span><strong>₦11,500</strong></div>`)}${note('Only this latest quotation can be accepted. Any change to the work requires a new quotation.')}<form data-submit="accept-quote">${check('I approve the described work and total charge.')}<button class="primary">Accept quotation</button></form><div class="fixed-cta">${action('Ask a question','quote-question','secondary')}</div>`;
case 'c-report':return `<div class="eyebrow">SERVICE REPORT / SV-1028</div><h1>A job well done.</h1>${pill('Awaiting your acknowledgement')}${card(`<h3>Cooker servicing</h3><p>Flame ports cleaned. Hose replaced. Final checks recorded.</p>${info('shield','Checklist completed','Recorded by the assigned technician')}${info('box','Materials used','1 × gas hose · 2 metres')}${info('file','Evidence','2 attached service photographs')}`)}<form data-submit="acknowledge">${check('I have reviewed the recorded work and report.')}<button class="primary">Acknowledge service</button></form><div class="fixed-cta">${button('Report a concern','c-thread','secondary')}</div><p style="margin-top:16px">Your acknowledgement does not replace the recorded safety inspection.</p>`;
case 'c-wallet':return `<div class="eyebrow">YOUR PURCHASE CREDIT</div><h1>A little ready<br>for next time.</h1><div class="balance-card"><p>Available balance</p><div class="amount">₦12,500<span style="font-size:22px">.00</span></div>${icon('wallet')}<div style="margin-top:20px;font-size:15px;color:#c9e7cc">EasyGas purchase credit</div></div>${button('View credit options','c-credit','secondary')}${note('Online top-ups, bank transfers and withdrawals are unavailable.')}${heading('Recent transactions')}${card(`${row('Order payment','EG-1986 · 12 Oct','bag','c-order','<strong>−₦27,500</strong>')}${row('Verified credit','Cash funding · 10 Oct','wallet','c-credit','<strong>+₦40,000</strong>')}`)}`;
case 'c-credit':return `<h1>Credit & redemption</h1><p>Keep track of verified funding and refunds.</p>${card(`<div class="row">${tile('wallet')}<div><h3>Purchase credit</h3><span class="small-note">Available balance · ₦12,500</span></div></div>`)}${note('Funding is verified independently. Online top-ups, transfers, withdrawals and points-to-cash conversion are unavailable.')}${card(`${row('Refund request RF-008','In review · 29 Oct','refresh','c-refund',pill('Pending','amber'))}${row('Verified funding','10 Oct · Reference CR-004','check','c-wallet')}`)}${button('Ask about a credit','c-thread','secondary')}`;
case 'c-rewards':return `<div class="eyebrow">EASYREWARDS</div><h1>A little more,<br>with every refill.</h1><div class="gold-card"><div class="row spread"><span>Your available points</span>${icon('gift')}</div><div class="amount">1,250</div><p>Separate from your purchase credit.</p></div>${card(`<h3>You’re ready for your next reward.</h3><p>Apply points to eligible purchases when the programme is active.</p>${button('Explore an offer','c-offer','secondary')}`)}${heading('Your points history')}${card(`${row('Eligible order reward','EG-1986 · 12 Oct','gift','c-order','<strong>+125 pts</strong>')}${row('Points used','EG-1842 · 21 Sep','bag','c-order','<strong>−500 pts</strong>')}`)}${button('Invite someone to EasyGas','c-account','secondary')}<div class="pin-note small-note">Offers and earning depend on the currently approved programme policy.</div>`;
case 'c-offer':return `<div class="big-check">${icon('gift')}</div><h1>Make your next<br>order go further.</h1><p>Delivery discount · 500 points</p>${card(`<h3>₦1,000 off an eligible order</h3><p>One use per customer. Valid until the offer expiry. Exclusions and order discount limits apply.</p>${info('clock','Available until 30 November','Subject to the approved offer budget')}${info('shield','Check eligibility at checkout','Delivery and excluded items may not qualify.')}`)}${action('Use offer on my next order','offer')}<p class="center" style="margin-top:15px">Points are only spent when your eligible order is confirmed.</p>`;
case 'c-profiles':return `<h1>Your cooking rhythm.</h1><p>Purchase history that helps you plan ahead.</p>${card(`<div class="row">${tile('cylinder')}<div class="grow"><h3>Home kitchen</h3><span class="small-note">12.5 kg cylinder profile</span></div>${pill('Active')}</div><div class="divider"></div><h2>Next refill: about 6 days</h2><p>Based on verified purchase intervals.</p>${button('View cooking profile','c-profile','secondary')}`)}${action(icon('plus')+' Add a cooking profile','add-profile','secondary')}`;
case 'c-profile':return `<div class="eyebrow">HOME KITCHEN / 12.5 KG</div><h1>Know your rhythm.</h1><p>Plan around the way you cook.</p>${card(`<h3>Estimated next refill</h3><div style="font-size:36px;font-weight:750;margin:12px 0">About 6 days</div><p>This is a purchase-history estimate, not a measured gas level.</p><div class="chart">${[40,62,55,80,70,95].map(h=>`<div class="bar" style="height:${h}%"></div>`).join('')}</div><div class="chart-labels"><span>May</span><span>Jun</span><span>Jul</span><span>Aug</span><span>Sep</span><span>Oct</span></div>`)}${button('Plan my refill','c-plans')}<div class="fixed-cta">${action('Tell us how it’s going','feedback','secondary')}</div>`;
case 'c-plans':return `<h1>Your next refill,<br>thoughtfully planned.</h1><p>A reminder to make room for what matters.</p>${card(`<div class="row spread"><h3>Home kitchen</h3>${pill('Active')}</div>${info('calendar','Thursday, 5 November','Preferred refill date · no automatic charge')}${info('cylinder','12.5 kg profile','Home · '+state.location)}<div class="btn-row">${action('Edit plan','edit-plan','secondary')}${action('Pause','pause-plan','secondary')}</div>`)}${action(icon('plus')+' Create a refill plan','edit-plan')}${button('Manage recurring orders','c-recurring','text-button')}`;
case 'c-recurring':return `<h1>Make it a routine.</h1><p>You stay in control of every authorisation.</p>${card(`<h3>Home refill · Every 30 days</h3><p>Next scheduled request · 5 November</p>${info('wallet','Cash on delivery','Maximum authorised total · ₦30,000')}${info('shield','No automatic electronic debit','Orders are only created if current policy, availability and your limit allow it.')}<div class="btn-row">${action('Edit limits','recurring','secondary')}${action('Pause orders','pause-plan','secondary')}</div>`)}${action(icon('plus')+' Set up a recurring order','recurring')}`;
case 'c-smart':return `<div class="icon-tile" style="margin-bottom:18px">${icon('flame')}</div><h1>Right on time.</h1><p>Refill suggestions built around verified purchases.</p>${card(`<h3>Home kitchen</h3><p>Based on your history, you may need a refill in about 6 days. Your cooking habits may change this.</p>${button('Order a refill','c-gas')}`)}${row('Refill reminders','Manage consent and quiet hours','bell','c-preferences')}${row('Your cooking profiles','Review history and estimates','chart','c-profiles')}`;
case 'c-notices':return `<h1>Your updates</h1><div class="row spread"><p>All the good-to-knows.</p>${action('Mark all read','read-all','text-button')}</div>${card(row('Your delivery is on the way','EG-2048 · 10 minutes ago','truck','c-track',state.noticeRead?'':pill('New')))}${card(row('Appointment confirmed','Cooker servicing · Tomorrow','calendar','c-booking'))}${card(row('Refill reminder','Your home profile · Today','flame','c-profile'))}`;
case 'c-account':return accountScreen('customer');
case 'c-personal':return `<h1>Your details</h1><form data-submit="personal">${field('name','Full name','Aisha Bello','text','required')}${field('email','Email address','aisha@example.test','email','readonly')}<p>For an email change, contact support so we can verify your identity.</p><button class="primary">Save changes</button></form>`;
case 'c-security':return `<h1>Safe and secure.</h1>${card(`<h3>Your password</h3><p>Use a unique password of at least 12 characters.</p>${action('Change password','password','secondary')}`)}${heading('Active sessions')}${card(`${row('This iPhone','Current session · Lagos','user',null,pill('Current'))}${row('Browser session','Last active yesterday','file',null,action('Revoke','revoke','text-button'))}`)}${action('Verify password for sensitive actions','verify-password','secondary')}`;
case 'c-privacy':return `<h1>Your data.<br>Your choice.</h1><p>Manage your information and privacy requests.</p>${card(`<h3>Export your data</h3><p>Request a copy of your account and activity records. Password verification is required.</p>${action('Request data export','export','secondary')}`)}${card(`<h3>Account deletion request</h3><p>We review requests, including records that need to be retained for financial or safety obligations.</p>${action('Request account deletion','delete-account','danger')}`)}${button('Read our privacy policy','c-policies','text-button')}`;
case 'c-preferences':return `<h1>Keep it your way.</h1><form data-submit="preferences"><label class="checkbox-row"><input type="checkbox" checked><span><strong>Refill reminders</strong><br>Helpful nudges based on your profile.</span></label><label class="checkbox-row"><input type="checkbox" checked><span><strong>Appointment reminders</strong><br>Updates for your upcoming service.</span></label><label class="checkbox-row"><input type="checkbox"><span><strong>Offers & recommendations</strong><br>Choose to hear about eligible offers.</span></label>${select('start','Quiet hours start · Lagos time',['9 PM','8 PM','10 PM'])}${select('end','Quiet hours end · Lagos time',['8 AM','7 AM','9 AM'])}<button class="primary">Save preferences</button></form>`;
case 'c-help':return `<h1>Here to help.</h1><p>Answers and a little peace of mind.</p>${card(`${row('Talk to support','Orders, bookings and account help','headset','c-support')}${row('Gas safety','Handling and care guidance','shield','c-policies')}${row('Delivery & refunds','Read current customer policies','truck','c-policies')}`)}${note('If you suspect a gas leak, stop using the appliance, avoid ignition sources and seek qualified assistance. Use the locally approved emergency guidance.')}`;
case 'c-support':return `<h1>A conversation<br>away.</h1><p>Get help with orders, appointments or your account.</p>${card(row('Question about my delivery','Open · Updated 10 minutes ago','headset','c-thread',pill('1 new')))}${action(icon('plus')+' Start a conversation','new-support')}`;
case 'c-thread':return `<div class="status-strip">${icon('headset')} Delivery question · Open</div><div class="chat-bubble mine">Hi, could you confirm my delivery window for EG-2048?</div><div class="chat-time" style="text-align:right">You · 11:25 AM</div><div class="chat-bubble">Hi Aisha. Your selected window is 2–6 PM today. We’ll keep the order timeline updated as your delivery progresses.</div><div class="chat-time">EasyGas Support · 11:28 AM</div><form data-submit="reply">${textarea('message','Your message','Write a reply…')}<button class="primary">Send message ${icon('arrow')}</button></form>`;
case 'c-policies':return `<h1>Clear from<br>the start.</h1><p>Review the latest published customer policies.</p>${['Delivery information','Refunds & purchase credit','Privacy policy','Terms & conditions','Gas handling & safety','Service booking terms'].map(t=>card(`<h3>${t}</h3><p>Read the effective policy and its version before agreeing to an order or service.</p>${action('Read policy '+icon('arrow'),'policy','text-button')}`)).join('')}`;
default:return '';
}}
function accountScreen(persona){const fieldRole=persona!=='customer';return `<div class="row" style="margin-bottom:24px"><div class="avatar large">${persona==='driver'?'JE':persona==='technician'?'JT':'AB'}</div><div><h2 style="margin:0">${persona==='driver'?'James E.':persona==='technician'?'James T.':'Aisha Bello'}</h2><span class="small-note">${fieldRole?(persona==='driver'?'Delivery partner':'Service technician'):'aisha@example.test'}</span></div></div>${fieldRole?card(`<div class="row">${tile('pin')}<div><h3>Lagos branch</h3><span class="small-note">Access follows your current assignment.</span></div></div>`):''}${!fieldRole?card(`${row('Personal details','Manage your profile','user','c-personal')}${row('My addresses',state.location,'pin','c-addresses')}${row('Wallet & credit','Verified purchase credit','wallet','c-wallet')}${row('EasyRewards','Points, offers & history','gift','c-rewards')}`):''}${card(`${row('Security & sessions','Password and signed-in devices','shield','c-security')}${row('Preferences','Consent and quiet hours','settings','c-preferences')}${row('Account & privacy','Exports and privacy requests','file','c-privacy')}${row('Help & support','We’re here to help','headset',persona==='driver'?'d-support':'c-support')}`)}${!fieldRole?card(`${row('Cooking gas profiles','Your purchase-history estimates','chart','c-profiles')}${row('Refill plans','Preferred dates & recurring orders','calendar','c-plans')}`):''}${action(icon('logout')+' Sign out','signout','secondary')}`}
function authScreen(id){if(id==='a-welcome')return `<img class="auth-logo" src="assets/logo.png" alt="EasyGas"><img class="auth-hero" src="assets/cooking.webp" alt="More cooking, less worry"><div class="eyebrow">AFFORDABLE · FLEXIBLE · COMMITTED</div><h1>More cooking.<br>Less worry.</h1><p>Order gas, care for your equipment and keep your kitchen moving.</p>${button('Get started '+icon('arrow'),'a-register')}<div class="fixed-cta">${button('I already have an account','a-login','secondary')}</div>`;if(id==='a-verify')return `<div class="big-check">${icon('file')}</div><h1>Check your email.</h1><p>If there’s an active account for this email, you’ll receive the next steps when email delivery is available.</p>${note('Links expire and can only be used once. Never share your password or verification link.')}${button('Back to sign in','a-login')}`;const register=id==='a-register',recover=id==='a-recover';return `<img class="auth-logo" src="assets/logo.png" alt="EasyGas"><h1>${recover?'A fresh start.':register?'Make yourself<br>at home.':'Welcome back.'}</h1><p>${recover?'Enter the email linked to your account.':'Good energy starts here.'}</p><form data-submit="${recover?'recover':'login'}">${register?field('fullname','Full name','','text','required autocomplete="name"'):''}${field('email','Email address','','email','required autocomplete="email" placeholder="you@example.com"')}${!recover?field('password','Password','','password','required minlength="12" autocomplete="'+(register?'new-password':'current-password')+'"'):''}${register?check('I agree to the published terms and privacy policy.'):''}<button class="primary">${recover?'Request reset link':register?'Create account':'Sign in'}</button></form>${!recover?button('Forgot your password?','a-recover','text-button'):''}<div class="fixed-cta">${button(register?'Already have an account?':'New to EasyGas?',register?'a-login':'a-register','secondary')}</div>`}
function driverScreen(id){const job=()=>card(`<div class="row spread"><strong>EG-2048</strong>${pill('Ready for pickup','amber')}</div><h2 style="margin-top:14px">Aisha Bello</h2><p>Home · Lekki Phase 1<br>2.5 kg refill · 1 cylinder</p><div class="row spread"><span class="small-note">Cash on delivery</span><strong>₦9,500</strong></div><div class="btn-row">${button('View delivery','d-job')}${button('Collection','d-pickup','secondary')}</div>`);switch(id){case 'd-home':return `<div class="eyebrow">YOUR WORKDAY</div><h1>Morning, James.</h1><p>One safe delivery at a time.</p><div class="metric-grid"><div class="metric">${icon('truck')}<strong>4</strong><span>Assigned deliveries</span></div><div class="metric">${icon('check')}<strong>2</strong><span>Completed today</span></div></div>${heading('Up next','d-tasks')}${job()}${card(row('Pending synchronisation','1 device record needs verification','refresh','d-offline',pill('1','amber')))}${note('Collect only the recorded amount. A delivery is complete after server verification and handover proof.')}`;case 'd-tasks':return `<h1>Your deliveries</h1><p>Only your current branch assignments appear here.</p><div class="segmented"><button class="active">Assigned</button><button data-go="d-offline">Pending sync</button></div>${job()}${card(row('EG-2049 · Victoria Island','12.5 kg refill · 2 PM – 6 PM','truck','d-job'))}${card(row('EG-2051 · Lekki','6 kg cylinder · 2 PM – 6 PM','cylinder','d-job'))}`;case 'd-job':return `<div class="row spread"><h1>EG-2048</h1>${pill('Assigned')}</div>${info('user','Aisha Bello','Recipient for this delivery')}${info('pin','12 Adeola Street','Lekki Phase 1, Lagos · Near the pharmacy')}${info('calendar','Today · 2 PM – 6 PM','Customer-selected delivery window')}${card(`<h3>What you’re delivering</h3><p>2.5 kg LPG refill<br>Assigned cylinder · EG-CYL-0184</p><div class="divider"></div><div class="summary-row total"><span>Collect cash</span><strong>₦9,500</strong></div>`)}${button('Confirm collection','d-pickup')}<div class="btn-row">${action('Contact recipient','contact','secondary')}${button('Report an issue','d-issue','secondary')}</div>${note('No live GPS or arrival estimate is available. Use the recorded address and confirmed order events.')}`;case 'd-pickup':return `<h1>Ready to go?</h1><p>Check every item against this order before collection.</p><form data-submit="pickup">${card(`<h3>EG-2048 · Collection checklist</h3>${check('Cylinder serial matches EG-CYL-0184.','serial')}${check('All assigned items are present.','items')}${check('Recorded safety eligibility is current.','safety')}`)}${note('Never collect a quarantined or mismatched cylinder. Report the issue to dispatch.')}<button class="primary">Confirm collection</button></form><div class="fixed-cta">${button('There’s a problem','d-issue','secondary')}</div>`;case 'd-proof':return `<div class="eyebrow">HANDOVER / EG-2048</div><h1>One final check.</h1><p>Complete only after all items are received.</p><form data-submit="delivery">${field('code','Customer’s 6-digit code','','text','required inputmode="numeric" pattern="[0-9]{6}" maxlength="6" placeholder="000000"')}${field('cash','Cash collected (₦)','9500','number','required min="9500" max="9500"')}${check('The recipient received every item in this order.','handover')}${check('The exact recorded cash amount was collected.','cashconfirmed')}${note('No partial handover or proof override. If anything is missing or the code fails, contact dispatch.')}<button class="primary">Verify & complete delivery</button></form><div class="fixed-cta">${button('Can’t complete this delivery','d-issue','secondary')}</div>`;case 'd-issue':return `<h1>Safety comes first.</h1><p>Tell dispatch what happened. Don’t mark an incomplete delivery as delivered.</p><form data-submit="delivery-issue">${select('reason','Reason',['Customer unavailable','Address inaccessible','Confirmation code issue','Unsafe cylinder / suspected leak','Damaged or missing item','Other'])}${textarea('detail','What happened?','Record the issue and what you need next.')}${check('The goods remain in my custody until an authorised return or handover.')}<button class="primary">Send issue to dispatch</button></form>${button('Return guidance','d-return','text-button')}`;case 'd-return':return `<h1>A safe return.</h1>${pill('Awaiting branch reconciliation','amber')}${info('cylinder','EG-CYL-0184','Remains in recorded delivery custody')}${card(`<h3>Return all assigned goods</h3><p>Bring the cylinder and every undelivered item to the branch. The authorised receiving team must inspect, receive and reconcile the return.</p><p>Damaged or unsafe cylinders must be quarantined. Returning goods does not automatically restock them.</p>`)}${button('Contact dispatch','d-support')}<div class="fixed-cta">${button('View delivery','d-job','secondary')}</div>`;case 'd-offline':return `<h1>Waiting to sync.</h1><p>Device records are not completed deliveries.</p>${note('Your encrypted record is awaiting server verification. Keep the device record until the outcome is confirmed.')}${card(`<h3>EG-2048 · Handover recorded</h3><p>Today, 2:42 PM · Cash recorded ₦9,500</p>${pill('Pending verification','amber')}<div class="fixed-cta">${action('Synchronise now','sync')}</div>${action('Discard device record','discard-sync','text-button')}`)}<p>Expired sessions, reassignment or a changed order may require dispatch review. A rejected record never completes the server order.</p>`;case 'd-support':return `<h1>Dispatch is here.</h1><p>Get help with an assigned delivery.</p>${card(row('Issue with EG-2048','Open dispatch conversation','headset','c-thread'))}${button('Report a delivery issue','d-issue')}${info('shield','For urgent safety concerns','Follow your approved branch emergency procedure and avoid further handling.')}`;case 'd-account':return accountScreen('driver');default:return ''}}
function technicianScreen(id){const appointment=()=>card(`<div class="row spread">${pill('Scheduled')}${icon('wrench')}</div><h2 style="margin-top:14px">Cooker servicing</h2><p>10 AM – 12 PM · Aisha Bello<br>Home · Lekki Phase 1</p>${button('Open job','t-job','secondary')}`);switch(id){case 't-home':return `<div class="eyebrow">YOUR WORKDAY</div><h1>Good morning,<br>James.</h1><p>Care, precision and peace of mind.</p><div class="metric-grid"><div class="metric">${icon('calendar')}<strong>3</strong><span>Appointments today</span></div><div class="metric">${icon('file')}<strong>1</strong><span>Report to submit</span></div></div>${heading('Your next appointment','t-agenda')}${appointment()}${card(row('Keep safety first','Record an unsafe condition before work','shield','t-safety'))}`;case 't-agenda':return `<h1>Your agenda</h1><div class="chips">${['Today','Tomorrow','This week'].map((t,i)=>`<button class="chip ${!i?'active':''}" data-action="agenda">${t}</button>`).join('')}</div>${appointment()}${card(row('Gas safety check','2 PM – 4 PM · Victoria Island','shield','t-job'))}${card(row('Cooker installation','4 PM – 6 PM · Lekki','flame','t-job'))}`;case 't-job':return `<div class="eyebrow">JOB SV-1042</div><h1>Cooker servicing</h1>${pill('Assigned to you')}${info('pin','Home · Lekki Phase 1','12 Adeola Street · Near the pharmacy')}${info('calendar','Tuesday, 3 November','10 AM – 12 PM')}${card(`<h3>Customer’s equipment</h3><p>4-burner cooker. Uneven flame and a hose inspection requested.</p>`)}${button('Run safety checklist','t-checklist')}<div class="btn-row">${button('Quotation','t-quote','secondary')}${button('Materials','t-materials','secondary')}</div>${button('Service report','t-report','text-button')}${button('Report an unsafe condition','t-safety','text-button')}`;case 't-checklist':return `<h1>Check before<br>you begin.</h1><p>Approved checklist · Version 3</p><form data-submit="checklist">${card(`${check('Confirm equipment and customer details.','identity')}${check('Review cylinder and connection condition.','cylinder')}${check('Complete the approved leak-check procedure.','leak')}${check('Record ventilation and access conditions.','ventilation')}`)}${textarea('observations','Your observations','Add findings from the approved checklist.')}${note('An unsafe outcome must stop work. A checked box does not replace qualified inspection.') }<button class="primary">Record checklist</button></form><div class="fixed-cta">${button('Unsafe outcome · stop work','t-safety','danger')}</div>`;case 't-quote':return `<h1>Quote it clearly.</h1><p>Customer approval is required before additional work.</p><form data-submit="technician-quote">${textarea('scope','Work proposed','Describe the work and its limits.')}${field('labour','Labour charge (₦)','8000','number','required min="0"')}${select('material','Material',['Gas hose · 2 metres','Regulator','No materials'])}${field('quantity','Material quantity','1','number','required min="1" max="20"')}${field('valid','Valid until','2026-11-05','date','required')}${note('Submitting creates a new quotation version. Only the customer can accept it.')}<button class="primary">Send quotation for approval</button></form>`;case 't-materials':return `<h1>Every part,<br>accounted for.</h1><p>Job SV-1042 · Approved material reservation</p>${card(`<div class="row">${tile('box')}<div class="grow"><h3>Gas hose · 2 metres</h3><span class="small-note">Reserved 1 · Issued 1</span></div></div><div class="divider"></div><form data-submit="materials">${field('used','Used','1','number','min="0" max="1" required')}${field('returned','Returned','0','number','min="0" max="1" required')}${field('damaged','Damaged','0','number','min="0" max="1" required')}${textarea('reason','Variance / damage notes (if any)')}<button class="primary">Record material outcome</button></form>`)}<p>Used, returned and damaged quantities must reconcile to the issued amount.</p>`;case 't-report':return `<h1>Leave a clear<br>record.</h1><form data-submit="service-report">${textarea('work','Work completed','Summarise the work carried out.')}${textarea('checks','Final checks','Record results from the approved checklist.')}${select('outcome','Outcome',['Work complete · pending customer review','Further work required','Unsafe · work stopped'])}<label class="field">Photographic evidence</label><button type="button" class="photo-slot" data-action="photo">${icon('upload')} Attach service photographs</button>${check('Materials, findings and safety outcomes are accurately recorded.')}<button class="primary">Submit for customer review</button></form><p style="margin-top:16px">The customer acknowledges the report. Cash collection requires separate finance verification.</p>`;case 't-safety':return `<div class="icon-tile orange" style="margin-bottom:20px">${icon('warning')}</div><h1>Stop. Record.<br>Get support.</h1><form data-submit="safety">${select('category','Concern',['Suspected leak','Unsafe connection','Damaged equipment','Quarantined cylinder','Other unsafe condition'])}${textarea('detail','Observed condition','Be specific about the equipment, risk and next step.')}${check('I have stopped the affected work and followed the approved safety procedure.')}<button class="danger">Escalate safety concern</button></form>${note('Do not mark the job safe or complete while an unsafe condition remains unresolved.')}`;case 't-history':return `<h1>Your service history</h1><p>Recorded work and customer acknowledgement.</p>${card(row('SV-1028 · Cooker servicing','Completed · 28 October','check','t-report',pill('Recorded')))}${card(row('SV-1024 · Safety check','Work held · Safety follow-up','warning','t-safety',pill('Held','amber')))}${card(row('SV-1019 · Installation','Completed · 24 October','check','t-report'))}`;case 't-account':return accountScreen('technician');default:return ''}}
