function businessScreen(id){const key=id.slice(2);if(key==='dashboard')return `<div class="eyebrow">BUSINESS WORKSPACE</div><h1>Your business,<br>at a glance.</h1><p>Lagos branch · Today</p><div class="metric-grid">${[['Verified revenue','₦124,800','chart'],['Active orders','18','bag'],['Awaiting delivery','6','truck'],['Needs review','3','shield']].map(([t,v,i])=>`<div class="metric">${icon(i)}<strong>${v}</strong><span>${t}</span></div>`).join('')}</div><div class="quick-grid">${[['bag','New order','b-orders'],['users','Customers','b-customers'],['box','Stock','b-inventory'],['shield','Approvals','b-approvals']].filter(x=>allowed(x[2])).map(([i,t,g])=>`<button class="quick" data-go="${g}">${tile(i)}<span>${t}</span></button>`).join('')}</div>${heading('Needs your attention',allowed('b-approvals')?'b-approvals':null)}${card(`${row('3 approvals awaiting review','Prices, access and refunds','shield',allowed('b-approvals')?'b-approvals':'b-operations',pill('3','amber'))}${row('A delivery needs reassignment','EG-2049 · Check capacity','truck','b-deliveries')}`)}${heading('Recent orders','b-orders')}${card(row('EG-2048 · Aisha Bello','2.5 kg gas · ₦9,500','bag','b-detail',pill('On the way')))}`;
if(key==='detail')return businessDetail();if(key==='edit')return businessForm();if(key==='review')return businessReview();if(key==='verify')return `<h1>A quick<br>security check.</h1><p>Verify your password before a sensitive action.</p><form data-submit="reauth">${field('password','Your password','','password','required minlength="12" autocomplete="current-password"')}<button class="primary">Verify & continue</button></form><p style="margin-top:16px">Verification is temporary and does not replace independent approval.</p>`;
if(key==='import')return `<h1>Your catalogue,<br>in one go.</h1><p>Use the approved template to prepare a bulk import.</p>${card(`<h3>1. Start with the template</h3><p>Includes names, SKU, category and descriptions. New records start as drafts.</p>${action(icon('download')+' Download CSV template','template','secondary')}`)}${card(`<h3>2. Choose your file</h3><label class="field">CSV file<input type="file" id="csvFile" accept=".csv,text/csv"></label><div class="small-note">Review validation errors before importing. Existing SKUs cannot be silently overwritten.</div>`)}${note('Imports do not publish products, approve prices or invent available stock.')}${action('Review import','import-review')}`;
if(key==='workspace'){return `<h1>Your workspace.</h1><p>Clear groups. The tools your role needs.</p>${model.businessNavigation.map(g=>{const items=g.items.filter(i=>i.roles.includes(state.role));return items.length?`<div class="section-heading"><h2>${g.label}</h2></div>${card(items.map(i=>row(i.label,'',i.icon,'b-'+i.id)).join(''))}`:''}).join('')}${card(row('Branch & profile','Lagos branch · '+roleLabel(),'user','c-security'))}`}
const config=businessData[key];if(!config)return '';
return `<div class="eyebrow">${state.role==='owner'?'BUSINESS OVERVIEW':'LAGOS BRANCH'}</div><h1>${screenMeta().title}</h1><p>${config.subtitle}</p>${key==='readiness'?note('Release decision: NO-GO. A green build does not close business, security, recovery or device acceptance.'):''}${key==='finance'?'<div class="balance-card"><p>Verified receipts · Today</p><div class="amount">₦482,500</div>'+icon('wallet')+'</div>':''}${key==='reports'?'<div class="card"><div class="row spread"><h3>Verified sales</h3>'+pill('7 days')+'</div><div class="chart">'+[35,50,45,70,66,95,76].map(h=>'<div class="bar" style="height:'+h+'%"></div>').join('')+'</div><div class="small-note">Based on verified source records. Not a margin forecast.</div></div>':''}<label class="search-input">${icon('search')}<input placeholder="Search ${screenMeta().title.toLowerCase()}…" id="businessSearch" aria-label="Search records"></label><div class="chips"><button class="chip active" data-action="filter">All</button><button class="chip" data-action="filter">Needs attention</button><button class="chip" data-action="filter">Lagos branch</button></div><div id="businessResults">${businessRows(config)}</div>${key==='products'?`<div class="btn-row">${action(icon('plus')+' Add product','business-new')}${button('Import','b-import','secondary')}</div>`:action(config.action+(key==='approvals'?' '+icon('arrow'):''),'business-new')}${['settings','staff','credits','approvals','policies'].includes(key)?'<div class="pin-note small-note">Sensitive actions require recent password verification and the applicable independent approvals.</div>':''}`}
function businessRows(config,query=''){const rows=config.rows.filter(r=>r.join(' ').toLowerCase().includes(query.toLowerCase()));return rows.map(([t,s,status])=>card(`<button class="list-row" data-go="${state.context==='approvals'?'b-review':'b-detail'}" style="padding:0;border:0;align-items:flex-start">${tile(config.icon)}<span class="grow"><strong>${t}</strong><span>${s}</span><span style="margin-top:10px">${pill(status,['Pending','Unassigned','Variance','Open','In review','Awaiting approval','Owner review','Finance review','2 reviews','Draft'].includes(status)?'amber':status==='Critical'||status==='Quarantined'||status==='Blocked'?'red':'')}</span></span>${icon('chevron')}</button>`)).join('')||empty('search','No matching records','Try another name, reference or filter.')}
function businessDetail(){const c=businessData[state.context]||businessData.products;return `<div class="eyebrow">LAGOS BRANCH / RECORD DETAILS</div><h1>${c.rows[0]?.[0]||'Business record'}</h1>${pill(c.rows[0]?.[2]||'Recorded')}${card(`<h3 style="margin-top:7px">${c.rows[0]?.[1]||'View the authoritative source before making a change.'}</h3>${info(c.icon,'Current record','Version 4 · Last updated today, 10:45 AM')}${info('shield','Access & scope',roleLabel()+' · '+(state.role==='owner'?'Owner access':'Lagos branch only'))}`)}${['staff','settings','policies','products'].includes(state.context)?note('Changes to price, publication, access or policy follow the shared approval workflow.'):''}${button(state.context==='approvals'?'Review proposal':'View or propose a change',state.context==='approvals'?'b-review':'b-edit')}${heading('Record history')}${card(`${info('clock','Record created','Yesterday, 9:32 AM')}${info('check','Last verified update','Today, 10:45 AM')}`)}${['deliveries','cylinders','inventory'].includes(state.context)?button('Record an exception','b-incidents','secondary'):''}`}
const formFields={products:()=>field('name','Product name','','text','required')+field('sku','Unique SKU','','text','required')+select('category','Category',['Gas cylinders','Accessories','Cookers','Service materials'])+textarea('description','Description','Describe the product and safety information.'),staff:()=>field('name','Staff name','','text','required')+field('email','Work email','','email','required')+select('branch','Branch',['Lagos'])+note('An invitation creates an account without staff privileges. Role grants require a separate independently approved request.'),customers:()=>field('name','Customer name','','text','required')+field('email','Email address','','email','required')+select('branch','Branch',['Lagos'])+note('Account access requires verified recovery. Never share staff passwords or create a default customer password.'),orders:()=>select('customer','Customer',['Aisha Bello','Kunle Adeyemi'])+select('product','Product',['Cooking gas refill','6 kg empty cylinder','Gas hose'])+field('quantity','Quantity','1','number','required min="1"')+select('address','Delivery address',['Home · Lekki','Office · Lagos Island']),inventory:()=>select('product','Stock item',['6 kg empty cylinder','Gas hose','Regulator'])+field('quantity','Received quantity','','number','required min="1"')+field('reference','Supplier / source reference','','text','required')+textarea('notes','Receipt evidence'),cylinders:()=>field('serial','Unique cylinder serial','','text','required')+select('capacity','Capacity',['6 kg','12.5 kg','25 kg','50 kg'])+textarea('inspection','Inspection and acquisition evidence')+note('Registration does not certify the cylinder or make it eligible for dispatch.'),settings:()=>select('setting','Setting',['Gas pricing','Gas quantity policy','Delivery fee','Location availability','Loyalty programme'])+field('value','Proposed value','','text','required')+field('effective','Requested effective date','','date')+textarea('reason','Business reason','Explain the change and attach evidence.'),policies:()=>select('kind','Policy',['Delivery','Refunds','Privacy','Terms','Services'])+textarea('text','Proposed revision')+field('version','Version / change reference','','text','required'),credits:()=>select('request','Request kind',['Verified funding','Order refund','Service refund'])+select('customer','Customer',['Aisha Bello','Kunle Adeyemi'])+field('source','Source order or funding reference','','text','required')+textarea('evidence','Reason and evidence'),campaigns:()=>field('title','Campaign title','','text','required')+select('audience','Eligible audience',['Opted-in refill profiles','Opted-in customers'])+textarea('message','Message')+field('budget','Approved offer budget reference','','text','required')+note('Consent, offer eligibility, budget, frequency and quiet hours are rechecked at delivery.'),incidents:()=>select('category','Category',['Delivery exception','Cylinder safety','Finance reconciliation','Service safety','System incident'])+select('severity','Severity',['Normal','High','Critical'])+textarea('detail','Observed issue, evidence and required next step'),bookings:()=>select('customer','Customer',['Aisha Bello','Kunle Adeyemi'])+select('service','Service',['Cooker servicing','Gas safety check'])+field('date','Available date','','date','required')+select('slot','Available appointment',['10 AM – 12 PM','2 PM – 4 PM'])};
function businessForm(){const key=state.context,c=businessData[key]||businessData.products,fields=formFields[key]||(()=>field('title','Record title','','text','required')+select('branch','Branch',['Lagos'])+textarea('evidence','Details, reason and supporting evidence'));return `<div class="eyebrow">${c.action}</div><h1>${['settings','policies'].includes(key)?'Propose a change.':key==='staff'?'Invite a colleague.':'Clear details.<br>Better records.'}</h1><form data-submit="business">${fields()}${check('I have reviewed the source records and branch scope.')}<button class="primary">${['settings','policies','credits','campaigns'].includes(key)?'Submit for independent review':key==='staff'?'Create invitation':'Save record'}</button></form><p style="margin-top:16px">The server checks your role, scope and the action’s current approval requirements.</p>`}
function businessReview(){return `<div class="eyebrow">APPROVAL AP-021 / LAGOS</div><h1>Review the<br>whole picture.</h1>${pill('Awaiting independent reviews','amber')}${card(`<h3>Gas price change</h3><p>Proposed by Finance O. · Today, 11:05 AM</p><div class="summary-row"><span>Current rate</span><strong>₦1,800/kg</strong></div><div class="summary-row"><span>Proposed rate</span><strong>₦1,850/kg</strong></div><div class="divider"></div><h3>Reason & evidence</h3><p>Updated supplier cost with documented margin review. Source reference attached.</p>`)}${info('shield','Independent owner + finance','The requester cannot approve their own request.')}${info('clock','Current version checked','Stale or expired proposals cannot activate.')}${textarea('decision','Review reason','Record your independent decision and evidence.')}<div class="btn-row">${action('Reject','reject','secondary')}${action('Review & approve','approve')}</div><div class="fixed-cta">${button('Verify password','b-verify','text-button')}</div>`}
function empty(ico,title,text,go,label){return `<div class="empty-state">${tile(ico)}<h2>${title}</h2><p>${text}</p>${go?button(label||'Explore',go):''}</div>`}
function stateScreen(){const name=screenMeta()?.title||'this screen';if(state.view==='loading')return `<div class="skeleton short"></div><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton short"></div><p role="status">Loading ${esc(name.toLowerCase())}…</p>`;if(state.view==='error')return empty('refresh','Let’s try that again.','We couldn’t load this information. Your existing records have not changed.')+action('Retry','retry');if(state.view==='restricted')return empty('shield','This area is restricted.','Your current role or session does not allow this action. Sign in again or contact your workspace owner.')+action('Go to my workspace','workspace');if(state.view==='empty')return empty(screenMeta()?.icon||'box','Nothing here just yet.',name==='My orders'?'Your confirmed orders and updates will appear here.':'When there’s activity to show, you’ll find it here.',state.persona==='customer'?'c-shop':state.persona==='driver'?'d-tasks':state.persona==='technician'?'t-agenda':'b-workspace',state.persona==='customer'?'Explore EasyGas':'Back to workspace');return ''}
function renderScreen(){const id=state.screen;if(state.view!=='ready'&&state.view!=='offline')return stateScreen();const content=id.startsWith('c-')?customerScreen(id):id.startsWith('a-')?authScreen(id):id.startsWith('d-')?driverScreen(id):id.startsWith('t-')?technicianScreen(id):businessScreen(id);return (state.view==='offline'?note('You’re offline. Displayed records may be stale. New actions need server verification.'):'')+(content||empty('warning','Screen unavailable','Return to your workspace to continue.'))}
function roleLabel(){return ({owner:'Business owner',manager:'Branch manager',finance:'Finance officer',inventory:'Inventory officer',sales:'Sales attendant',dispatcher:'Dispatcher',administrator:'Administrator',service_manager:'Service manager',safety_officer:'Safety officer'})[state.role]||state.role}
function allowed(id){if(['b-detail','b-edit','b-verify'].includes(id))return model.screens.find(s=>s.id==='b-'+state.context)?.roles?.includes(state.role)===true;if(id==='b-review')return model.screens.find(s=>s.id==='b-approvals')?.roles?.includes(state.role)===true;const m=model.screens.find(s=>s.id===id);return !m?.roles||m.roles.includes(state.role)}
function navigation(){const selected=model.screens.filter(s=>s.persona===state.persona&&(state.persona!=='business'||allowed(s.id)));const query=$('screenSearch').value.toLowerCase();const groups=[...new Set(selected.map(s=>s.group))];$('screenNav').innerHTML=groups.map(g=>{const list=selected.filter(s=>s.group===g&&s.title.toLowerCase().includes(query));return list.length?`<div class="nav-group">${g}</div>${list.map(s=>`<button class="screen-link ${s.id===state.screen?'active':''}" data-go="${s.id}" ${s.id===state.screen?'aria-current="page"':''}>${icon(s.icon)}<span>${s.title}</span></button>`).join('')}`:''}).join('')||'<p>No matching screens.</p>';$('personas').innerHTML=[['customer','Customer'],['driver','Driver'],['technician','Technician'],['business','Business']].map(([id,t])=>`<button data-persona="${id}" class="${state.persona===id?'selected':''}" ${state.persona===id?'aria-pressed="true"':'aria-pressed="false"'}>${t}</button>`).join('')}
function guide(){const m=screenMeta();const tips=m.persona==='driver'?['Assignment-scoped tasks; no administration sidebar.','Whole-order handover and exact cash amount.','Offline proof remains pending until verified.']:m.persona==='technician'?['Job-first navigation with safety before work.','Customer approval for quotation changes.','Customer acknowledgement stays separate.']:m.persona==='business'?['One mobile workspace, filtered by role.','Shared approval rules; no self-approval shortcut.','Cards replace dense desktop tables.']:['Five calm navigation destinations.','One clear primary action per step.','Estimates describe purchase history, never sensors.'];$('guide').innerHTML=`<div class="guide-label">${m.persona.toUpperCase()} / ${m.group.toUpperCase()}</div><h2>${m.title}</h2><p>${m.persona==='business'?'Your web workspace, reorganised for one-handed review and action.':'A familiar EasyGas experience, designed for the moment you’re in.'}</p><div class="guide-card"><h3>Interaction principles</h3><ul>${tips.map(t=>'<li>'+t+'</li>').join('')}</ul></div><div class="guide-card"><h3>Existing web relationship</h3><code>${m.webRoute}</code><p>${m.api}</p><p>Integration mapping only. This prototype never connects to the business database.</p></div>${state.persona==='business'?`<div class="guide-card"><label for="roleControl"><h3>Review role visibility</h3></label><select id="roleControl" class="studio-button" style="width:100%">${['owner','manager','finance','inventory','sales','dispatcher','administrator','service_manager','safety_officer'].map(r=>`<option value="${r}" ${state.role===r?'selected':''}>${({owner:'Business owner',manager:'Branch manager',finance:'Finance officer',inventory:'Inventory officer',sales:'Sales attendant',dispatcher:'Dispatcher',administrator:'Administrator',service_manager:'Service manager',safety_officer:'Safety officer'})[r]}</option>`).join('')}</select><p>Visibility follows the repository’s navigation allowlists. It does not grant API access.</p></div>`:''}<div class="guide-card"><h3>Foundation</h3><div class="swatches"><span class="guide-swatch" style="background:#006336"></span><span class="guide-swatch" style="background:#a7cd42"></span><span class="guide-swatch" style="background:#f3ae49"></span><span class="guide-swatch" style="background:#eaf5eb"></span><span class="guide-swatch" style="background:#142b20"></span></div><p>15 px minimum text · 44+ px touch areas · safe-area-aware layout · semantic light/dark surfaces.</p></div><div class="guide-card"><h3>${model.screens.length} designed screens</h3><p>Sample figures, dates, statuses and approval states are illustrative. Feature availability and economics require the existing backend controls.</p></div>`}
function render(){navigation();$('device').classList.toggle('dark',state.theme==='dark');$('appHeader').innerHTML=appHeader();$('app').innerHTML=renderScreen();$('tabbar').innerHTML=state.screen.startsWith('a-')?'':tabs();$('tabbar').style.display=state.screen.startsWith('a-')?'none':'flex';$('screenCaption').textContent=state.persona[0].toUpperCase()+state.persona.slice(1)+' / '+screenMeta().title;$('stateControl').value=state.view;$('themeToggle').innerHTML='◐ <span>'+(state.theme==='dark'?'Light mode':'Dark mode')+'</span>';guide()}
function navigate(id,replace=false){const next=model.screens.find(s=>s.id===id);if(!next)return;const from=state.screen;if(next.persona==='business'&&!allowed(id)){toast('This role cannot open that area.');return}if(!replace&&id!==from)state.history.push(from);const shared=['c-security','c-privacy','c-preferences','c-thread','c-notices','c-policies','c-support','c-help'];if(!(state.persona!=='customer'&&shared.includes(id)))state.persona=next.persona;state.screen=id;state.view='ready';if(id.startsWith('b-')&&!['b-detail','b-edit','b-review','b-import','b-verify','b-workspace'].includes(id))state.context=id.slice(2);$('sheetHost').innerHTML='';render();$('app').scrollTop=0;if(location.hash!=='#'+id)history.replaceState(null,'','#'+id)}
let toastTimer;function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3200)}
function sheet(title,body,footer=''){const previous=document.activeElement;$('sheetHost').innerHTML=`<div class="sheet-overlay"><section class="sheet" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="sheet-handle"></div><div class="row spread"><h2>${title}</h2><button class="back-button" data-action="close-sheet" aria-label="Close dialog">×</button></div>${body}${footer}</section></div>`;const focusable=$('sheetHost').querySelector('input,select,textarea,button');focusable?.focus();$('sheetHost').dataset.returnFocus=previous?.id||''}
function flowForm(title,body,submit,kind='generic'){sheet(title,`<form data-submit="${kind}">${body}<button class="primary">${submit}</button></form>`)}
function perform(name){switch(name){case 'back':{const previous=state.history.pop();navigate(previous||({customer:'c-home',driver:'d-home',technician:'t-home',business:'b-dashboard'})[state.persona],true);break}case 'close-sheet':$('sheetHost').innerHTML='';$('appHeader').querySelector('button')?.focus();break;case 'workspace':navigate(({customer:'c-home',driver:'d-home',technician:'t-home',business:allowed('b-dashboard')?'b-dashboard':'b-workspace'})[state.persona]);break;case 'location':if(state.persona!=='customer'){sheet('Lagos branch','<p>Your current branch and assignment determine the records you can access. Changing a branch requires the existing authorisation process.</p>',action('Close','close-sheet','secondary'));break}sheet('Where are we delivering?',`<p>Choose a saved delivery address or add the complete house address.</p>${row('Home','Lekki Phase 1, Lagos','pin','c-addresses')}${row('Office','Lagos Island','pin','c-addresses')}`,button('Add an address','c-addressform','secondary'));break;case 'add':state.cart++;toast('Added to your basket.');break;case 'remove':state.cart=0;render();break;case 'plus':state.quantity=Math.min(state.capacity,Math.round((state.quantity+.5)*10)/10);render();break;case 'minus':state.quantity=Math.max(.5,Math.round((state.quantity-.5)*10)/10);render();break;case 'select-address':state.location='Lekki, Lagos';navigate('c-checkout');toast('Delivery address selected.');break;case 'read-all':state.noticeRead=true;render();toast('Notifications marked as read.');break;case 'retry':state.view='ready';render();break;case 'offer':toast('Offer selected. Eligibility is checked at checkout.');navigate('c-gas');break;case 'feedback':flowForm('How is your refill going?',select('feedback','Choose an update',['Still cooking','Running low','Already refilled'])+textarea('notes','Notes (optional)'),'Save update');break;case 'edit-plan':flowForm('Plan your next refill',select('profile','Cooking profile',['Home kitchen · 12.5 kg'])+field('date','Preferred date','2026-11-05','date','required')+select('address','Delivery address',['Home · Lekki, Lagos']),'Save refill plan');break;case 'add-profile':flowForm('Your cooking profile',field('name','Profile name','','text','required placeholder="e.g. Home kitchen"')+select('capacity','Cylinder capacity',['6 kg','12.5 kg','25 kg'])+note('An estimate appears only when there is enough eligible purchase history.'),'Create profile');break;case 'recurring':flowForm('Authorise a recurring order',field('interval','Repeat every (days)','30','number','required min="7"')+field('ceiling','Maximum total (₦)','30000','number','required min="1"')+select('payment','Payment',['Cash on delivery'])+check('I authorise eligible COD requests within this limit. No electronic debit is authorised.'),'Save authorisation');break;case 'pause-plan':sheet('Pause this plan?','<p>No new requests will be generated while it is paused. Existing confirmed orders are unchanged.</p>',action('Pause plan','confirm-pause')+action('Keep active','close-sheet','text-button'));break;case 'confirm-pause':$('sheetHost').innerHTML='';toast('Plan paused. You can resume when you’re ready.');break;case 'password':flowForm('Change password',field('current','Current password','','password','required autocomplete="current-password"')+field('new','New password','','password','required minlength="12" autocomplete="new-password"'),'Change password');break;case 'verify-password':flowForm('Verify your password',field('password','Your password','','password','required minlength="12"'),'Verify password');break;case 'revoke':sheet('Revoke this session?','<p>The selected session will lose access. This device stays signed in.</p>',action('Revoke selected session','session-revoked')+action('Keep session','close-sheet','text-button'));break;case 'session-revoked':$('sheetHost').innerHTML='';toast('Selected session revoked.');break;case 'export':flowForm('Request a data export',field('password','Verify your password','','password','required minlength="12"')+note('Only your own account records are included.'),'Request export');break;case 'delete-account':flowForm('Request account deletion',textarea('reason','Reason for your request','Tell us what you would like us to review.')+check('I understand this request is reviewed against retention obligations.'),'Submit request');break;case 'new-support':flowForm('How can we help?',field('subject','Subject','','text','required')+textarea('message','Your message','Tell us what happened.'),'Start conversation','new-support');break;case 'policy':sheet('Published policy','<p>The production app will show the effective, independently published policy text and version from the existing policy service.</p><p>Design reference only: this screen does not supply legally approved text.</p>',action('Close','close-sheet','secondary'));break;case 'signout':sheet('Sign out of EasyGas?','<p>Your saved offline field records remain associated with this account. Confirm pending work before changing accounts.</p>',action('Sign out','confirm-signout')+action('Stay signed in','close-sheet','text-button'));break;case 'confirm-signout':navigate('a-login');break;case 'contact':sheet('Contact the recipient','<p>Use the contact details on your authorised assignment. Never share a delivery code with anyone other than the recipient.</p>',button('Ask dispatch for help','d-support','secondary'));break;case 'sync':toast('Synchronisation requested. Records await server verification.');break;case 'discard-sync':sheet('Discard this device record?','<p>The server order remains unchanged. Discard only after reviewing the outcome with dispatch.</p>',action('Discard record','discard-confirm','danger')+action('Keep record','close-sheet','text-button'));break;case 'discard-confirm':$('sheetHost').innerHTML='';toast('Device record discarded. Server status unchanged.');break;case 'business-new':if(state.context==='approvals'){navigate('b-review');break}if(['reports','audit','readiness'].includes(state.context)){sheet(state.context==='readiness'?'Release blockers':'Report options',select('range','Date range',['Last 7 days','This month','Custom range'])+note(state.context==='readiness'?'Production remains NO-GO until the remaining gates are accepted.':'Report scope follows your role and selected branch.'),action('Apply selection','report-filter','secondary'));break}navigate('b-edit');break;case 'approve':sheet('Independent approval','<p>Verify your password and review the current proposal version. Your decision does not activate a request until all required independent approvals pass.</p>'+field('password','Your password','','password','required minlength="12"')+check('I am independent of the requester and have reviewed the evidence.'),action('Record independent approval','approve-confirm'));break;case 'approve-confirm':{const host=$('sheetHost');if(!host.querySelector('input[type=checkbox]')?.checked||host.querySelector('input[type=password]').value.length<12){toast('Verify your password and confirm independent review.');break}$('sheetHost').innerHTML='';toast('Review recorded. Remaining approvals are still required.');break}case 'reject':flowForm('Reject this proposal',textarea('reason','Decision reason','Explain the reason and any required correction.'),'Record rejection');break;case 'template':{const a=document.createElement('a');const blob=new Blob(['name,sku,category,description\nSample accessory,DESIGN-SAMPLE,Accessories,Design template example only\n'],{type:'text/csv'});a.href=URL.createObjectURL(blob);a.download='easygas-design-import-template.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);break}case 'import-review':sheet('Review import','<p>Design example: 3 valid new draft rows, 1 duplicate SKU to fix.</p>'+note('Validation errors must be corrected before importing. No existing products are overwritten.'),action('Return to file','close-sheet','secondary'));break;case 'photo':toast('Photo attachment selected. No image is uploaded in this prototype.');break;case 'cancel-booking':flowForm('Request cancellation',textarea('reason','Reason for cancellation','Explain why you need to cancel.')+check('I have reviewed the applicable cancellation policy.'),'Submit cancellation request');break;case 'quote-question':navigate('c-thread');break;case 'filter':sheet('Filter records',select('status','Status',['All statuses','Needs attention','Active','Draft'])+select('branch','Branch',['Lagos'])+field('date','From date','','date'),action('Apply filters','report-filter'));break;case 'report-filter':$('sheetHost').innerHTML='';toast('Filters applied to the example view.');break;case 'agenda':toast('Agenda date filter selected.');break;case 'activeorders':toast('Showing active example orders.');break;case 'pastorders':sheet('Past orders',card(row('EG-1986 · Delivered','12.5 kg refill · 12 Oct','check','c-order')));break;default:toast('Selection recorded in this design preview.')}}
document.addEventListener('click',event=>{const el=event.target.closest('button,[data-go]');if(!el)return;if(el.dataset.go){event.preventDefault();navigate(el.dataset.go);return}if(el.dataset.persona){state.persona=el.dataset.persona;state.history=[];state.role='owner';navigate(({customer:'c-home',driver:'d-home',technician:'t-home',business:'b-dashboard'})[state.persona],true);return}if(el.dataset.category){state.category=el.dataset.category;render();return}if(el.dataset.action){event.preventDefault();perform(el.dataset.action)}});
document.addEventListener('submit',event=>{const form=event.target.closest('form[data-submit]');if(!form)return;event.preventDefault();if(!form.reportValidity())return;const type=form.dataset.submit;if(type==='checkout')navigate('c-confirmation');else if(type==='login')navigate('c-home');else if(type==='recover')navigate('a-verify');else if(type==='booking'){navigate('c-booking');toast('Appointment request recorded.')}else if(type==='pickup'){navigate('d-proof');toast('Collection recorded.')}else if(type==='delivery'){state.completed=true;navigate('d-tasks');toast('Handover submitted for verification.')}else if(type==='delivery-issue'){navigate('d-return');toast('Issue recorded for dispatch review.')}else if(type==='safety'){navigate('t-job');toast('Work held. Safety concern escalated.')}else if(type==='technician-quote'){navigate('t-job');toast('Quotation sent for customer review.')}else if(type==='service-report'){navigate('t-history');toast('Report submitted for customer acknowledgement.')}else if(type==='checklist'){navigate('t-job');toast('Checklist outcome recorded.')}else if(type==='address'){navigate('c-addresses');toast('Address saved in the example journey.')}else if(type==='business'){navigate('b-detail');toast(['settings','policies','credits','campaigns'].includes(state.context)?'Proposal submitted for independent review.':'Example record saved.')}else if(type==='reauth'){navigate('b-review');toast('Password verified for the example review.')}else if(type==='refund'){navigate('c-credit');toast('Refund request is awaiting independent review.')}else if(type==='reply'){const val=new FormData(form).get('message');const bubble=document.createElement('div');bubble.className='chat-bubble mine';bubble.textContent=val||'Thank you.';form.before(bubble);form.reset();toast('Reply added to this example conversation.')}else if(type==='new-support'){navigate('c-thread');toast('Conversation opened.')}else{$('sheetHost').innerHTML='';toast(type==='acknowledge'?'Service acknowledgement recorded.':type==='accept-quote'?'Current quotation accepted.':'Changes saved in this example.')}});
document.addEventListener('input',e=>{if(e.target.id==='screenSearch')navigation();if(e.target.id==='productSearch')$('productResults').innerHTML=productCards(products.filter(p=>(state.category==='All'||p.kind===state.category)&&p.name.toLowerCase().includes(e.target.value.toLowerCase())));if(e.target.id==='businessSearch')$('businessResults').innerHTML=businessRows(businessData[state.context],e.target.value)});
document.addEventListener('change',e=>{if(e.target.id==='stateControl'){state.view=e.target.value;render()}if(e.target.id==='roleControl'){state.role=e.target.value;const first=model.screens.find(x=>x.persona==='business'&&allowed(x.id));navigate(first?.id||'b-workspace',true)}if(e.target.id==='capacity'){state.capacity=Number(e.target.value);state.quantity=Math.min(state.quantity,state.capacity);render()}if(e.target.id==='gasQuantity'){const n=Number(e.target.value);if(Number.isFinite(n)&&n>=.5&&n<=state.capacity&&Math.abs(n*2-Math.round(n*2))<.001){state.quantity=n;render()}else{toast('Choose a half-kilogram increment within your cylinder capacity.');e.target.value=state.quantity}}});
$('themeToggle').onclick=()=>{state.theme=state.theme==='light'?'dark':'light';render()};$('widthControl').onchange=e=>{$('device').style.width=e.target.value+'px'};$('reset').onclick=()=>{Object.assign(state,{persona:'customer',screen:'c-home',theme:'light',view:'ready',role:'owner',quantity:2.5,capacity:12.5,category:'All',cart:1,completed:false,history:[]});$('screenSearch').value='';$('device').style.width='390px';$('widthControl').value='390';history.replaceState(null,'','#c-home');render()};
document.addEventListener('keydown',e=>{const sheetNode=$('sheetHost').querySelector('.sheet');if(!sheetNode)return;if(e.key==='Escape'){perform('close-sheet');return}if(e.key==='Tab'){const targets=[...sheetNode.querySelectorAll('button:not(:disabled),input,select,textarea,a[href]')];const first=targets[0],last=targets.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(model.screens.some(s=>s.id===id))navigate(id,true)});
if(model.screens.some(s=>s.id===location.hash.slice(1)))navigate(location.hash.slice(1),true);else render();
window.EASYGAS_STUDIO={state,render,navigate,renderScreen,allowed};
if(new URLSearchParams(location.search).get('presentation')==='1')document.body.classList.add('presentation');
